ATTACH ':memory:' AS db2; CREATE TABLE db2.t2(x,y); CREATE TABLE db2.tx(x1,x2,y1,y2); CREATE TRIGGER db2.r1 AFTER UPDATE ON t2 BEGIN INSERT INTO tx VALUES(OLD.x,NEW.x,OLD.y,NEW.y); END; CREATE INDEX db2.i2 ON t2(x); INSERT INTO main.capture SELECT rowid,type,name,tbl_name FROM db2.sqlite_master ORDER BY rowid;